const round=x=>{const f=Math.floor(x);return x-f===.5?f+f%2:Math.round(x)};
export function createGohyeonLightLayer({manifest,indices,transmission}){
 if(manifest?.revision!=='GOHYEON_V3_VISIBLE_LIGHTING_R2'||manifest.width!==4294||manifest.height!==2400||!(indices instanceof Uint32Array)||!(transmission instanceof Float64Array)||indices.length!==manifest.count||transmission.length!==indices.length*3)throw Error('light input shape');
 for(let i=0;i<indices.length;i++){if(indices[i]>=4294*2400||(i&&indices[i]<=indices[i-1]))throw Error('light index bounds');for(let c=0;c<3;c++)if(!Number.isFinite(transmission[i*3+c])||transmission[i*3+c]<0||transmission[i*3+c]>1)throw Error('transmission');}
 return {apply(host,{nightMix,camera,state,sourceSHA}){if(!['OPEN','CLOSED'].includes(state)||sourceSHA!==manifest.sourceSHAs[state]||!Number.isFinite(nightMix)||nightMix<0||nightMix>1||!Array.isArray(camera)||camera.length!==4)throw Error('light state/source');const[x0,y0,w,h]=camera;if(![x0,y0,w,h].every(Number.isInteger)||x0<0||y0<0||w<1||h<1||x0+w>4294||y0+h>2400||host.length!==w*h*4)throw Error('camera');let writes=0;if(nightMix===0)return{writes};for(let i=0;i<indices.length;i++){const id=indices[i],x=id%4294-x0,y=Math.floor(id/4294)-y0;if(x<0||y<0||x>=w||y>=h)continue;const k=(y*w+x)*4;for(let c=0;c<3;c++)host[k+c]=round(255-(255-host[k+c])*(1-nightMix*(1-transmission[i*3+c])));writes++;}return{writes};}};
}
